    pianist: { namn: ["pianist", "pianisten", "flygel", "flygeln", "piano", "pianot", "dam", "damen"], kort: "en pianist", klicknamn: "pianisten", plats: "klubb", fast: true, person: true,
      beskrivning: "Den nya pianisten är en liten gråhårig dam som heter Mabel. Hon spelar boogie-woogie med underarmar som en hamnarbetare. Hon har inga vita handskar, och det tycker Moe är ett gott tecken." },
