    utpressningsbrev: { namn: ["utpressningsbrev", "utpressningsbrevet", "brev", "brevet", "hotbrev", "hotbrevet"], kort: "utpressningsbrevet", klicknamn: "utpressningsbrevet", plats: null, lasbar: true,
      beskrivning: [{ om: { inteFlagga: "vattenmarke" }, text: "Utpressningsbrevet, skrivet med lila bläck i en elegant handstil på ett tjockt, dyrt papper utan brevhuvud. Papperet känns nästan för fint för utpressning. Som om det hade något mer att berätta, om man bara såg på det i rätt ljus." },
        { om: { flagga: "vattenmarke" }, text: "Utpressningsbrevet med lila bläck. Mot ljuset syns vattenstämpeln: en liten krona och orden HOTEL MAJESTIC." }],
      lasText: "\"BORGMÄSTARE BIGSBY. DRA DIG UR VALET FÖRE DEBATTEN, ANNARS HISSAS DINA RÖDA LÅNGKALSONGER PÅ RÅDHUSETS FLAGGSTÅNG MEDAN HELA STAN LYSSNAR PÅ RADION. EN VÄN AV ORDNING.\"" },

