  ledtradar: [
    { om: { inteFlagga: "uppdrag" }, text: "Telefonen ringer. Svara." },
    { om: { inteBar: "kort", objektPa: ["kort", "lada"] }, text: "Ditt tunnelbanekort ligger i skrivbordslådan. Du behöver det för att åka tunnelbana." },
    { om: { inteBar: "ficklampa", objektPa: ["ficklampa", "lada"] }, text: "Det ligger något mer i skrivbordslådan som kan vara bra att ha med sig. Något som lyser." },
    { om: { inteFlagga: "radhus" }, text: "Gå till rådhuset vid torget på Boulevarden och prata med receptionisten. Fröken Prim sa åt dig vad du skulle säga." },
    { om: { inteFlagga: "klient" }, text: "Gå uppför trappan till borgmästarens kontor." },
    { om: { inteFlagga: "rockHamtad" }, text: "Kalsongerna stals från tvätteriet i gränden bakom urmakaren. Fru Grubb pratar bara med kunder. Är du kund där? Titta på skrivbordet hemma." },
    { om: { inteFlagga: "grubb" }, text: "Fråga fru Grubb om natten då kalsongerna stals. Fråga om allt: hur han såg ut, vad han sa, vad hon märkte." },
    { om: { inteFlagga: "vattenmarke" }, text: "Utpressningsbrevet är skrivet på fint papper. Håll upp det mot ett ljus, till exempel en lampa." },
    { om: { inteFlagga: ["gastbok", "piccoloVill"], inteBar: "autograf" }, text: "Vattenstämpeln pekar mot Hotel Majestic på östra Main Street. Gästboken i lobbyn skulle kunna avslöja vem som skriver med lila bläck. Prata med piccolon." },
    { om: { inteFlagga: ["gastbok", "autografFatt"] }, text: "Piccolon vill ha en autograf av Rex Rapp. Rex Rapp finns i radiohuset WGHR, norr om Blå Ostronet. Han tycker om smicker." },
    { om: { inteFlagga: ["gastbok", "conciergeBorta"] }, text: "Ge Rex Rapps autograf till piccolon." },
    { om: { inteFlagga: "gastbok" }, text: "Conciergen är borta. Läs gästboken." },
    { om: { inteFlagga: "vane", inteBar: "rock" }, text: "Kvinnan i lila sitter i hotellbaren, men baren kräver ytterrock. Din trenchcoat är på tvätt." },
    { om: { inteFlagga: "vane" }, text: "Prata med kvinnan i lila i hotellbaren. Lägg fram både vattenstämpeln och det lila bläcket från gästboken." },
    { om: { inteFlagga: "quiz" }, text: "Utroparen på Nöjespiren, söder om Pir 9 och öster om fiskmarknaden, släpper in den som klarar hans frågesport. Svaren finns runt om i stan. Prata med folk, till exempel damen vid fontänen och båtkarlen i parken." },
    { om: { inteBar: "kalsonger", inteFlagga: ["vunnit", "spoktag"] }, text: "Spöktåget på Nöjespiren är stängt och mörkt, men man kan gå in om man har ljus med sig. Ficklampan låg i skrivbordslådan." },
    { om: { inteBar: "kalsonger", inteFlagga: "vunnit" }, text: "Titta noga på skelettet i spöktåget." },
    { om: { inteFlagga: "losen" }, text: "Långkalsongerna ska tillbaka till borgmästaren. Men vill du ha alla poäng innan dess: den röda dörren i bakgatan i Chinatown vill ha ett lösenord, och Bennys lyckokakor vet mer än man tror." },
    { om: { inteBar: "skuldsedel", inteFlagga: "lou" }, text: "Titta på roulettbordet i spelhålan." },
    { om: { inteFlagga: "lou" }, text: "Konfrontera Lucky Lou på Nöjespiren med det du vet, och visa honom skuldsedeln." },
    { om: { inteFlagga: "polis" }, text: "Berätta för kommissarie O'Hara på polisstationen, västra Main Street, vilka som är skyldiga." },
    { om: { inteFlagga: "fiskvittne" }, text: "Fiskhandlaren på fiskmarknaden ser det mesta som händer i hamnen. Fråga honom om mannen i uniform som fru Grubb beskrev." },
    { om: { inteFlagga: "vunnit" }, text: "Lämna tillbaka långkalsongerna till borgmästaren i rådhuset." },
    { text: "Du har gjort allt. Ta en kopp kaffe. Om du har råd." },
  ],

